func enSame(emonT *testing.T, a *port.Cells, b *port.Cells, law string) int32 {
	port.AssertEq(emonT, port.CellsLen(a), port.CellsLen(b), law)
	var i int32 = 0
	for i < port.CellsLen(a) {
		port.AssertEq(emonT, port.CellsAt(a, i), port.CellsAt(b, i), law)
		i += 1
	}
	return 0
}

func TestTheOrderOfAResolutionDoesNotDependOnTheOrderOrRepeatsOfItsInputs(emonT *testing.T) {
	var l1 *port.Cells = port.NewCells()
	var l2 *port.Cells = port.NewCells()
	var e1 *port.Cells = port.NewCells()
	var e2 *port.Cells = port.NewCells()
	var i1 *port.Cells = port.NewCells()
	var i2 *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	port.CellsPush(l1, 1936744704)
	port.CellsPush(l1, engines.PkLangEng())
	port.CellsPush(l1, 1718771968)
	port.CellsPush(l2, 1718771968)
	port.CellsPush(l2, 1936744704)
	port.CellsPush(l2, engines.PkLangEng())
	port.CellsPush(l2, engines.PkLangEng())
	port.CellsPush(e1, engines.EngPpocr())
	port.CellsPush(e1, engines.EngTesseract())
	port.CellsPush(e2, engines.EngTesseract())
	port.CellsPush(e2, engines.EngPpocr())
	port.CellsPush(e2, engines.EngTesseract())
	port.CellsPush(i1, packdata.PkidTessFastSpa())
	port.CellsPush(i1, packdata.PkidPp5DetMobile())
	port.CellsPush(i2, packdata.PkidPp5DetMobile())
	port.CellsPush(i2, packdata.PkidTessFastSpa())
	port.CellsPush(i2, packdata.PkidPp5DetMobile())
	port.AssertEq(emonT, enResolve(engines.PclsLinux(), engines.PkfOsd(), l1, e1, i1, a), engines.PkerrOk(), "one order")
	port.AssertEq(emonT, enResolve(engines.PclsLinux(), engines.PkfOsd(), l2, e2, i2, b), engines.PkerrOk(), "another")
	enSame(emonT, a, b, "the same rows in the same order")
	port.AssertThat(emonT, engines.PkRows(a) > 6, "English, Spanish, French, OSD and three models, and PP-OCR's two unreadable languages")
}

