func TestResolutionRefusesWhatTheCatalogueAndTheTableDoNotHave(emonT *testing.T) {
	var langs *port.Cells = port.NewCells()
	var engs *port.Cells = port.NewCells()
	var installed *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var msg *strings.Builder = port.NewText()
	enCells1(engs, 99)
	port.AssertEq(emonT, enResolve(engines.PclsMacos(), 0, langs, engs, installed, out), engines.PkerrUnknownEngine(), "an engine that is not in the table")
	port.AssertEq(emonT, port.CellsAt(out, 0), 99, "the subject")
	engines.PkExplain(engines.PkerrUnknownEngine(), out, msg)
	port.AssertText(emonT, msg, "unknown engine: 99", "named")
	enCells1(engs, engines.EngPdfium())
	port.AssertEq(emonT, enResolve(engines.PclsMacos(), 0, langs, engs, installed, out), engines.PkerrNotOcr(), "a renderer does not read")
	enCells1(engs, engines.EngAppleVision())
	port.AssertEq(emonT, enResolve(engines.PclsWindows(), 0, langs, engs, installed, out), engines.PkerrEngineClass(), "Vision is not on Windows")
	var m2 *strings.Builder = port.NewText()
	engines.PkExplain(engines.PkerrEngineClass(), out, m2)
	port.AssertText(emonT, m2, "engine is not available on the platform class: \"apple-vision\" on \"windows\"", "both named")
	port.CellsDrop(engs, 0)
	port.AssertEq(emonT, enResolve(9, 0, langs, engs, installed, out), engines.PkerrUnknownClass(), "a class that is not one")
	port.AssertEq(emonT, port.CellsAt(out, 0), 9, "the subject")
	enCells1(installed, 99)
	port.AssertEq(emonT, enResolve(engines.PclsMacos(), 0, langs, engs, installed, out), engines.PkerrUnknownPack(), "an installed pack that is not in the catalogue")
	port.AssertEq(emonT, port.CellsAt(out, 0), 99, "the subject")
	port.CellsDrop(installed, 0)
	enCells1(langs, 0)
	port.AssertEq(emonT, enResolve(engines.PclsMacos(), 0, langs, engs, installed, out), engines.PkerrBadLanguage(), "no language is 0")
}

